INSERT INTO [dbo].[instructors] ([instructor_id], [seminar_id], [Name], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Description], [Email], [Phone], [Fax], [IsActive], [ImageName], [ImagePath], [DetailsHtml]) VALUES (1, 9, N'Professor Bayo Lawal', N'test', N'test', N'test', N'test', NULL, N'Nigeria', N'Bayo Lawal, Ph.D., FNSA , is Professor of Statistics at Kwara State University, Malete. Nigeria. His research focused on small samples in contingency tables, models for square tables having ordinal categories; categorical data analysis and overdispersed count regression models.He has taught graduate classes in categorical data analysis at Temple University, Medical University of South Carolina and St Cloud State University, MN. USA. ', N'blawal@loyabconsulting.com', N'123-123-1234', NULL, 1, N'DSC_1125.JPG', N'images/DSC_1125.JPG', N'<p style="text-align: left;">                              His methodological works have appeared in <a href="http://biomet.oxfordjournals.org/">Biometrika</a>, Biometrical Journal, Applied Statistics,                <a href="http://jscs.statjournals.net">Journal of Statistical Computation and Simulation</a>,               Australiaqn Journal of Statistics and Quality and Quantity amongst several others.              He is the author of Categorical data Analysis with SAS and SPSS (2003, Francis &amp;), and is recently published by Psychological Press (2012);                Applied Statistcal Methods in Agriculture, health and Life Sciences (2014, Springer) and is joint author of the text: Applied Statistics: Regression and Analysis of variance (2013, Philadelphia Press of America).             <br><br>                      He has served as Chair of department of Statistics both at the University of Ilorin,                 Nigeria and St. Cloud State University, Mn. USA. He has also served as Dean of the School of Sciences at Auburn University at Montgomery, Alabama, USA                and Dean of the School of Arts and Sciences at the American University of Nigeria, Yola. Nigeria.                He is a fellow of the Nigerian Statistical Association and former editor-in-Chief of the Journal of the Nigerian Statistical Association            </p>')
INSERT INTO [dbo].[instructors] ([instructor_id], [seminar_id], [Name], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Description], [Email], [Phone], [Fax], [IsActive], [ImageName], [ImagePath], [DetailsHtml]) VALUES (2, NULL, N'Professor Felix Famoye', N'test', N'test', N'test', N'california', NULL, N'Nigeria', N'Felix Famoye is a professor and a consulting statistician in the Department of Mathematics at Central Michigan University, Mount Pleasant, Michigan, USA. He received his B.Sc. (Hons) degree in statistics from the University of Ibadan, Ibadan, Nigeria. ', N'felix@loyabconsulting.com', N'612-327-2304', NULL, 1, N'Felix.jpg', N'images/Felix.jpg', N'<p style="text-align: left;">                                  He received his Ph.D. degree in statistics from the University of Calgary under the Canadian Commonwealth Scholarship.                   He is a co-author of the books “Lagrangian Probability Distributions”, “Statistics for Biological and Health Sciences”                  and “Applied Statistics: Regression and Analysis of Variance.”              <br><br>                  He is an Editor-in-Chief of Journal of Statistical Distributions and Applications.                  He is a recipient of the College of Science &amp; Technology Outstanding Teaching Award, Central Michigan University Excellence in Teaching Award,                  College of Science &amp; Technology Award for Outstanding Research, and President’s Award for Outstanding Research and Creative Activity.                   He was a Fulbright Fellow at the University of Lagos, an elected member of International Statistical Institute                  and an elected Fellow of American Statistical Association.            </p>')
INSERT INTO [dbo].[instructors] ([instructor_id], [seminar_id], [Name], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Description], [Email], [Phone], [Fax], [IsActive], [ImageName], [ImagePath], [DetailsHtml]) VALUES (3, 9, N'Felix Famoye', N'test', N'test', N'test', N'test', NULL, N'Ghana', N'Felix Famoye is a professor and a consulting statistician in the Department of Mathematics at Central Michigan University,                   Mount Pleasant, Michigan, USA. He received his B.Sc. (Hons) degree in statistics from the University of Ibadan, Ibadan, Nigeria.', N'felix@statisticalconsulting.com', N'543-897-2345', NULL, 1, N'Felix.jpg', N'images/Felix.jpg', N'<p>                  He received his Ph.D. degree in statistics from the University of Calgary under the Canadian Commonwealth Scholarship.                   He is a co-author of the books “Lagrangian Probability Distributions”, “Statistics for Biological and Health Sciences”                  and “Applied Statistics: Regression and Analysis of Variance.”  </p>            <p>                 He is an Editor-in-Chief of Journal of Statistical Distributions and Applications.                  He is a recipient of the College of Science &amp; Technology Outstanding Teaching Award, Central Michigan University Excellence in Teaching Award,                  College of Science &amp; Technology Award for Outstanding Research, and President’s Award for Outstanding Research and Creative Activity.            </p>             <p>                 He was a Fulbright Fellow at the University of Lagos, an elected member of International Statistical Institute                  and an elected Fellow of American Statistical Association.            </p>')
